import org.jetbrains.annotations.Nullable;

public class Extras {
    // como una función de Java sin anotación de nulabilidad
    public static String sinAnotar() { return null; }

    // como una función de Java anotada con @Nullable
    @Nullable
    public static String anotada() { return null; }
}

// ---- Plataforma.kt ----
fun main() {
    val a: String? = Extras.anotada()
    println("anotada: ${a?.length ?: "sin valor"}")

    try {
        val b: String = Extras.sinAnotar()      // compila: el tipo que ve Kotlin es String!
        println("sin anotar: ${b.length}")
    } catch (e: Exception) {
        println("sin anotar, al asignar: ${e::class.simpleName}")
    }

    val c = Extras.sinAnotar()                  // tipo inferido de plataforma
    try {
        println(c.length)                       // Kotlin no avisa: falla al usarlo
    } catch (e: Exception) {
        println("sin anotar, al usar: ${e::class.simpleName}")
    }
}

