import kotlinx.coroutines.*

// Una "pantalla" de juguete. En Android, este alcance lo da lifecycleScope o viewModelScope.
class Pantalla {
    private val alcance = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    fun abrir() {
        alcance.launch {
            try {
                println("corrutina: pido el versículo del día...")
                delay(2000)                     // la red tarda
                println("corrutina: llegó, lo dibujo")
            } catch (e: CancellationException) {
                println("corrutina: me cancelaron, no dibujo nada")
                throw e
            }
        }
        Thread {
            Thread.sleep(2000)
            println("hilo suelto: llegó, intento dibujar en una pantalla destruida")
        }.start()
    }

    fun destruir() {
        println("la pantalla se destruye")
        alcance.cancel()                        // cancela todo lo que se lanzó adentro
    }
}

fun main() = runBlocking {
    val p = Pantalla()
    p.abrir()
    delay(500)
    p.destruir()
    delay(2200)
    println("fin")
}

// res/layout/pantalla_racha.xml: un TextView con id «racha» y un Button con id «sumar»
class PantallaRachaActivity : AppCompatActivity() {
    private var dias = 0

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.pantalla_racha)
        val racha = findViewById<TextView>(R.id.racha)
        racha.text = "Racha: $dias días"
        findViewById<Button>(R.id.sumar).setOnClickListener {
            dias += 1
            racha.text = "Racha: $dias días"   // hay que acordarse de tocar la vista
        }
    }
}

@Composable
fun Racha(dias: Int, onSumar: () -> Unit) {
    Column {
        Text("Racha: $dias días")
        Button(onClick = onSumar) { Text("Sumar un día") }
    }
}

@Composable
fun PantallaRacha() {
    var dias by remember { mutableStateOf(0) }
    Racha(dias = dias, onSumar = { dias += 1 })
}

// Un juguete: cada "alcance" anota qué estados lee, y solo esos alcances se vuelven a ejecutar
// cuando un estado cambia. Es la idea de la recomposición de Compose, sin su compilador ni su runtime.
object Rastreo { var actual: Alcance? = null }

class Estado<T>(private var v: T) {
    private val lectores = mutableSetOf<Alcance>()
    var valor: T
        get() { Rastreo.actual?.let { lectores.add(it) }; return v }
        set(nuevo) {
            if (nuevo == v) return
            v = nuevo
            lectores.toList().forEach { it.correr() }
        }
}

class Alcance(val nombre: String, private val cuerpo: () -> Unit) {
    var corridas = 0
    fun correr() {
        corridas++
        val anterior = Rastreo.actual
        Rastreo.actual = this
        cuerpo()
        Rastreo.actual = anterior
    }
}

fun main() {
    val usuario = Estado("Juan")
    val toques = Estado(0)

    val titulo = Alcance("Titulo") { println("  Titulo dibuja: Hola, ${usuario.valor}") }
    val contador = Alcance("Contador") { println("  Contador dibuja: ${toques.valor} toques") }

    println("primera composición")
    titulo.correr()
    contador.correr()

    repeat(3) {
        println("toque")
        toques.valor += 1
    }
    println("cambia el usuario")
    usuario.valor = "Ana"

    println("corridas: Titulo=${titulo.corridas}, Contador=${contador.corridas}")
}
